<script lang="ts">
 import { goto } from '$app/navigation';
 import { Scan, ArrowUpRight, ShieldCheck, Eye, EyeOff } from 'lucide-svelte';
 import { api,json } from '@lib/api';
 import { user, loadSession } from '@lib/session';
 import Button from './ui/button.svelte';
 let {register=false}=$props();let name=$state(''),email=$state(''),password=$state(''),confirm=$state(''),show=$state(false),busy=$state(false),error=$state('');
 async function submit(e:SubmitEvent){e.preventDefault();error='';busy=true;try{const result=await api('/auth/'+(register?'register':'login'),json('POST',register?{full_name:name,email,password,confirm_password:confirm}:{email,password}));user.set(result.user);await loadSession();await goto('/dashboard');}catch(e){error=(e as Error).message;}finally{busy=false;}}
</script>
<div class="auth-page"><a href="/" class="brand"><Scan size={28}/><span>visionary<span class="brand-ai">ai</span></span></a><div class="auth-layout"><div class="auth-story"><span class="tiny-dot"></span><h1>Every frame.<br/>A little more insight.</h1><p>Your own space to explore, save, and understand the world around you.</p><div><ShieldCheck size={22}/><span>On-device intelligence.<br/>Private discoveries.</span></div></div><div class="auth-form"><h2>{register?'Create your workspace':'Welcome back.'}</h2><p>{register?'A fresh perspective starts here.':'Sign in to your Visionary AI account.'}</p><form onsubmit={submit}>{#if register}<label>Full name<input required maxlength="120" autocomplete="name" bind:value={name} placeholder="Your full name"/></label>{/if}<label>Email address<input required type="email" autocomplete="email" bind:value={email} placeholder="you@example.com"/></label><label>Password<div class="password-field"><input required minlength="8" maxlength="128" type={show?'text':'password'} autocomplete={register?'new-password':'current-password'} bind:value={password} placeholder="At least 8 characters"/><button type="button" class="icon-btn" aria-label={show?'Hide password':'Show password'} onclick={()=>show=!show}>{#if show}<EyeOff size={17}/>{:else}<Eye size={17}/>{/if}</button></div></label>{#if register}<label>Confirm password<input required minlength="8" type={show?'text':'password'} autocomplete="new-password" bind:value={confirm} placeholder="Enter your password again"/></label>{/if}{#if error}<div class="notice error" role="alert">{error}</div>{/if}<Button type="submit" disabled={busy}>{busy?'Please wait…':register?'Create account':'Sign in'}<ArrowUpRight size={17}/></Button></form><p class="auth-switch">{register?'Already have an account?':'New to Visionary AI?'} <a href={register?'/login':'/register'}>{register?'Sign in':'Create an account'}</a></p><a class="guest-link" href="/detect/image">Continue exploring as a guest <ArrowUpRight size={14}/></a></div></div><footer>Camera frames are processed on your device. <a href="/docs">Privacy & model guide</a></footer></div>
